    background-color: var(--xt-bg) !important;
    border-radius: 12px !important; /* 恢复好看的手账圆角 */
    box-shadow: 0 4px 20px rgba(0,0,0,0.06) !important; 

    /* 铺满全屏的虚线信纸背景，严格 40px 一行 */
